/* reset / base */
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.65 var(--font);
  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
a{color:var(--accent);text-underline-offset:2px}
h1,h2,h3{font-family:var(--font-display);line-height:1.25;margin:0 0 .5em}
img{max-width:100%}

/* decorative backdrop (always on) */
/* Optional local background image under a readability overlay. */
html{background:var(--bg)}          /* solid base behind the backdrop */
body{background:transparent}        /* let the backdrop show through   */
body::before{                       /* the wash itself */
  content:"";position:fixed;inset:0;z-index:-2;pointer-events:none;
  background:
    radial-gradient(1200px 820px at 12% -12%, var(--accent-weak), transparent 60%),
    radial-gradient(1000px 720px at 100% 6%,  var(--accent-weak), transparent 55%),
    var(--bg);
}
html[data-has-bg] body::before{
  background:var(--bg-image) center center/cover no-repeat;opacity:.28;
}
html[data-has-bg] body::after{                    /* scrim toward --bg for legibility */
  content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:var(--bg);opacity:.42;
}

/* app grid */
.app{display:grid;grid-template-columns:minmax(340px,42%) 1fr;gap:0;
  max-width:1500px;margin:0 auto;min-height:100vh}
.left{position:sticky;top:0;align-self:start;height:100vh;display:flex;flex-direction:column;
  gap:14px;padding:18px;border-right:1px solid var(--border);background:transparent}
.right{padding:26px clamp(16px,3vw,40px);min-width:0}

/* video */
.player-wrap{position:relative;background:#000;border-radius:var(--radius);overflow:hidden;
  box-shadow:var(--shadow);flex:0 0 auto}
#player{display:block;width:100%;max-height:46vh;background:#000}

/* timeline TOC (left-bottom) */
.toc{flex:1 1 auto;min-height:0;overflow:auto;border:1px solid var(--border);
  border-radius:var(--radius);background:var(--surface);padding:8px}
.toc-head{display:flex;align-items:center;justify-content:space-between;gap:8px;
  padding:8px 10px 10px}
.toc-head-label{font:600 12px/1 var(--font);letter-spacing:.08em;text-transform:uppercase;
  color:var(--muted)}
.toc-toggle-all{border:1px solid var(--border);background:transparent;color:var(--muted);
  cursor:pointer;font:600 10px/1 var(--font);letter-spacing:.04em;padding:5px 8px;
  border-radius:var(--radius-sm);white-space:nowrap}
.toc-toggle-all:hover{background:var(--surface-2);color:var(--text)}
.toc-item{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:baseline;
  width:100%;text-align:left;border:0;background:transparent;color:var(--text);
  cursor:pointer;padding:7px 10px;border-radius:var(--radius-sm);font:14px/1.35 var(--font)}
.toc-item:hover{background:var(--surface-2)}

